#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back({(int)e[1], e[2]});
    const long long INF = 1000000000000000000LL;
    vector<int> indeg(n + 1, 0), order;
    for (const vector<long long>& e : edges) indeg[e[1]]++;
    for (int v = 1; v <= n; v++) {
        if (indeg[v] == 0) order.push_back(v);
    }
    for (size_t i = 0; i < order.size(); i++) {
        for (const auto& edge : adj[order[i]]) {
            indeg[edge.first]--;
            if (indeg[edge.first] == 0) order.push_back(edge.first);
        }
    }
    vector<long long> dist(n + 1, INF);
    dist[1] = 0;
    for (int u : order) {
        if (dist[u] >= INF) continue;
        for (const auto& edge : adj[u]) {
            if (dist[u] + edge.second < dist[edge.first]) dist[edge.first] = dist[u] + edge.second;
        }
    }
    if (dist[n] < INF) cout << dist[n] << "\n";
    else cout << "unreachable\n";

    return 0;
}

